 881		\leanok
 882		Let $K$ be a finite integral domain, let $c\in\N$, and let
 883		$f,g\in K^{c+1}$ be distinct coefficient vectors. Their polynomials
 884		$p_f(T)=\sum_{i=0}^{c}f_iT^i$ and $p_g(T)=\sum_{i=0}^{c}g_iT^i$
 885		agree at at most $c$ elements of $K$.
 886		The coefficient representation is injective, preserves evaluation,
 887		and has natural degree at most $c$.
 888		This is a formalization-only auxiliary for the Schwartz--Zippel step
 889		in the proof of Lemma~\ref{lem:qld-xz-lines}
 890		(\texttt{14\_analysis\_of\_the\_pauli\_basis\_test.tex:955}).
1150				\approx_{\delta_Q}
1151				\Big( \sum_{\substack{a,b:\\ \alpha a + \beta b = c}}
1152				\hat{M}^{(\mathrm{Point},Z),z}_{b} \,
1153				\hat{M}^{(\mathrm{Point},X),x}_{a}
1154				\Big)_{\mathsf{B}\mathsf{A}''}\,.
1155			\end{gather}
1156		\end{enumerate}
1157		Furthermore, all symmetric equivalents of these approximations also hold.
1158	\end{lemma}
1159	\begin{proof}
1160		\uses{lem:qld-4-10, fact:data-processing}
1161		Define
1162		$\hat{Q}^{x,z,\alpha,\beta}_{c}
1163		= \sum_{a,b \,:\, \alpha a + \beta b = c} \hat{Q}^{x,z}_{a,b}$,
1164		a coarse-graining of the projective measurement of
1165		Lemma~\ref{lem:qld-4-10}, hence itself projective. A uniformly random
1166		point of $\F_q^{2m+2}$ has uniformly random coordinates $(x,z)$, so the
1167		self-consistency and consistency properties follow from those of
1168		$\{\hat{Q}^{x,z}_{a,b}\}$ established in Lemma~\ref{lem:qld-4-10}
1169		together with Lemma~\ref{fact:data-processing}, which shows that
1170		coarse-graining the outcomes preserves the $\delta_Q$ bounds.
1171	\end{proof}
