1950			\sum_{f_X,f_Z} \bra{\hat\psi}
1951			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1952			\big(\Id - \hat{Q}^{x,z}_{f_X(x),f_Z(z)}
